def main():
    if not os.path.isfile("_config.yml"):
        sys.exit("ERROR: no _config.yml here. cd to your site repo root first.")

    print("Writing content files")
    for path, body in FILES.items():
        os.makedirs(os.path.dirname(path), exist_ok=True)
        with open(path, "w", encoding="utf-8", newline="\n") as fh:
            fh.write(body)
        print("  wrote   " + path)

    print("\nRemoving demo content")
    demo = []
    for pattern in ("_projects/*_project.md", "_news/*.md", "_posts/*.md",
                    "_teachings/data-science-fundamentals.md",
                    "_teachings/introduction-to-machine-learning.md"):
        demo.extend(glob.glob(pattern))
    if demo:
        for path in sorted(demo):
            os.remove(path)
            print("  removed " + path)
    else:
        print("  (none left to remove)")

    print("\nPatching page settings")
    patches = [
        ("_pages/projects.md",
         "display_categories: [work, fun]",
         "display_categories: [research]"),
        ("_pages/teaching.md",
         "{% include calendar.liquid calendar_id='test@gmail.com' timezone='Asia/Shanghai' %}\n\n",
         ""),
        ("_config.yml",
         "  A simple, whitespace theme for academics. Based on [*folio](https://github.com/bogoli/-folio) design.",
         "  Zach Abdulrahman -- applied mathematician at NYU Courant. Optimization, numerical analysis, and dynamical systems."),
    ]
    for path, old, new in patches:
        if not os.path.isfile(path):
            print("  SKIP    " + path + " (not found)")
            continue
        text = open(path, encoding="utf-8").read()
        if old not in text:
            print("  SKIP    " + path + " (already changed, or text not found -- edit by hand)")
            continue
        with open(path, "w", encoding="utf-8", newline="\n") as fh:
            fh.write(text.replace(old, new, 1))
        print("  patched " + path)

    print("""
Done.

Next:
    bundle exec jekyll serve      # check http://localhost:4000/
    git add -A
    git commit -m "Personalise site content"
    git push

Still to do by hand:
  - replace assets/img/prof_pic.jpg with your own photo (same filename)
  - drop your CV PDF at assets/pdf/cv.pdf, then uncomment cv_pdf in _data/socials.yml
    and update cv_pdf in _pages/cv.md
  - set nav: false in _pages/blog.md, publications.md, repositories.md,
    profiles.md and dropdown.md if you have not already
""")


if __name__ == "__main__":
    main()
